method incr_list(l: seq<int>) returns (result: seq<int>)
    requires l != null
    ensures |result| == |l| && forall i :: 0 <= i < |l| ==> result[i] == l[i] + 1
{
    result := l;
    var i := 0;
    while i < |l|
        invariant 0 <= i <= |l| && |result| == |l| && forall j :: 0 <= j < i ==> result[j] == l[j] + 1
    {
        result[i] := l[i] + 1;
        i := i + 1;
    }
}
